Bash(NODE_TLS_REJECT_UNAUTHORIZED=0 bun -e "
import { createDirectus, rest, staticToken, readRoles, deleteRole, readPolicies, deletePolicy } from ''@directus/sdk'';

const client = createDirectus\(''https://backend.alcstronghold.local''\)
  .with\(staticToken\(process.env.DIRECTUS_TOKEN\)\)
  .with\(rest\(\)\);

// Get and delete Master/Moderator roles
const roles = await client.request\(readRoles\(\)\);
for \(const role of roles\) {
  if \(role.name === ''Master'' || role.name === ''Moderator''\) {
    console.log\(''Deleting role:'', role.name, role.id\);
    await client.request\(deleteRole\(role.id\)\);
  }
}

// Get and delete related policies
const policies = await client.request\(readPolicies\(\)\);
for \(const policy of policies\) {
  if \(policy.name.includes\(''Master''\) || policy.name.includes\(''Moderator''\)\) {
    console.log\(''Deleting policy:'', policy.name, policy.id\);
    await client.request\(deletePolicy\(policy.id\)\);
  }
}

console.log\(''Cleanup complete''\);
")
